<script setup lang="ts">import type {Scenario} from '../types/domain';import {num} from '../utils/format';defineProps<{scenario:Scenario}>()</script><template><div class="scenario-strip"><span>快照 <b>v{{scenario.version}}</b></span><span>截止 <b>{{num(scenario.deadline)}} 小时</b></span><span>抽样 <b>{{scenario.samples}}</b></span><span>seed <b>{{scenario.seed}}</b></span><template v-if="scenario.snapshot.crews?.length"><span>班组 <b>{{scenario.snapshot.crews.map(c=>c.crew_id+'×'+c.capacity).join(' · ')}}</b></span><span>派工 <b>优先级→任务ID · 不抢占</b></span><span>模型 <b>独立 Beta-PERT λ=4 · 班组受限</b></span></template><span v-else>模型 <b>独立 Beta-PERT λ=4</b></span></div></template>